//! Env-gated parity corpus for the Rust port of `tools/contract_validate.py`.
//!
//! The corpus is generated by the Python side, so these tests are `#[ignore]`d:
//! a plain `cargo test` reports them as ignored, never as passed. Run them with
//! the corpus variable set and `--ignored`:
//!
//! ```text
//! .venv/Scripts/python.exe .tmp_adversarial540/rust-schema/gen_schema_corpus.py
//! BOARDWISE_540C_SCHEMA_CORPUS=.tmp_adversarial540/rust-schema/schema-corpus.jsonl \
//!   bash .tmp_540/rust-buildtools/cargo-local.sh test -p boardwise-core \
//!     --test schema_parity -- --ignored
//! ```
//!
//! Each row carries raw JSON *text* for the schema and the instance (so `1e999`
//! and the non-JSON `NaN` token survive exactly) plus the outcome Python reaches.
//! The test recomputes that classification and demands the same answer: `ok`,
//! `instance`, `schema` or `load`. A boolean-instead-of-number, an unknown
//! keyword in an unreached branch, a circular `$ref` or a non-finite literal
//! therefore has to fall at the same gate on both sides.

use boardwise_core::schema::{check_schema, ensure_finite, validate_document};
use serde_json::Value;
use std::fs;
use std::path::{Path, PathBuf};

/// A corpus path from the environment, relative ones resolved against the
/// repository root (cargo runs test binaries with the crate directory as cwd).
fn corpus_path(variable: &str) -> Option<PathBuf> {
    let value = std::env::var(variable).ok()?;
    let path = PathBuf::from(value);
    if path.is_absolute() {
        Some(path)
    } else {
        Some(
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .ancestors()
                .nth(3)
                .expect("repository root")
                .join(path),
        )
    }
}

fn corpus_rows(path: &Path) -> Vec<Value> {
    let text = fs::read_to_string(path).expect("corpus is readable");
    text.lines()
        .filter(|line| !line.trim().is_empty())
        .map(|line| serde_json::from_str(line).expect("corpus row is JSON"))
        .collect()
}

/// The same four-way classification the Python generator recorded.
fn rust_outcome(schema_text: &str, instance_text: &str) -> &'static str {
    let Ok(schema) = serde_json::from_str::<Value>(schema_text) else {
        return "load";
    };
    let Ok(instance) = serde_json::from_str::<Value>(instance_text) else {
        return "load";
    };
    if ensure_finite(&instance).is_err() || ensure_finite(&schema).is_err() {
        // `tools/differential.py` reads the input and the schema through
        // `load_path`, so a non-finite literal in either is a load refusal.
        return "load";
    }
    if check_schema(&schema).is_err() {
        return "schema";
    }
    if validate_document(&instance, &schema).is_err() {
        "instance"
    } else {
        "ok"
    }
}

#[test]
#[ignore = "requires the Python schema-validation corpus"]
fn schema_validation_matches_python_corpus() {
    let path = corpus_path("BOARDWISE_540C_SCHEMA_CORPUS")
        .expect("set BOARDWISE_540C_SCHEMA_CORPUS to the Python schema corpus");
    let rows = corpus_rows(&path);
    let mut failures = Vec::new();
    let mut mismatches = 0_usize;
    for row in &rows {
        let name = row["name"].as_str().expect("name");
        let schema_text = row["schema"].as_str().expect("schema");
        let instance_text = row["instance"].as_str().expect("instance");
        let expected = row["python"].as_str().expect("python outcome");
        let got = rust_outcome(schema_text, instance_text);
        if got != expected {
            mismatches += 1;
            if failures.len() < 20 {
                failures.push(format!("{name}: rust {got}, python {expected}"));
            }
        }
    }
    assert!(
        mismatches == 0,
        "{mismatches} of {} cases fall at a different gate: {failures:#?}",
        rows.len()
    );
    assert!(
        rows.len() >= 90,
        "the corpus must cover every failure class"
    );
}
